#include "display.h"
#include "vo_view.hpp"

// VO-6: generated by tools/make_engine.py. The screen: md_rig.hpp draws the
// design's parts from art.h; voices/vo_view.hpp draws what changes shape.
namespace mmvo6 {
inline void display_reset(DisplayState& state) {
    state.hit.initialized = 0;
    state.hit.age = 1 << 20;
}

inline void display(DisplayState& state, const opxy::draw::Input& input, Frame& frame) {
    md::view::begin(frame, input);
    state.hit.update(input);
    const md::view::Moment moment = {state.hit.age, input.reduced_motion};
    md::rig::draw(frame, art::parts, art::effects, art::members, art::machines[0], input.slots, moment);
    md::vo_6::view(frame, input.slots, moment);
    static const char* const steps2[2] = {"OFF", "ON"};
    static const char* const steps4[21] = {"-", "B", "D", "F", "G", "H", "J", "K", "L", "M", "N", "P", "R", "RR", "S", "SJ", "T", "TJ", "TH", "V", "Z"};
    for (u32 i = 0; i < 4; ++i)
        if (input.shown[i] == 2) opxy::draw::copy(frame.header[i], opxy::draw::header_capacity,
                                                  steps2[(static_cast<u32>(md::positive(input.slots[2])) >> 16) * 2u >> 15]);
    for (u32 i = 0; i < 4; ++i)
        if (input.shown[i] == 4) opxy::draw::copy(frame.header[i], opxy::draw::header_capacity,
                                                  steps4[(static_cast<u32>(md::positive(input.slots[4])) >> 16) * 21u >> 15]);
}
}
